# Settings for running an experiment on HPC Vega (SLURM). Sourced by every
# script in hpc/vega/.
#
# Do not edit this file on the cluster: a run refuses to start from
# uncommitted code (provenance.py). Put local values in
# hpc/vega/config.local.sh, which git ignores, or in the environment.
# Anything set there wins over the defaults below.

HERE_VEGA="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$HERE_VEGA/../.." && pwd)"
[ -f "$HERE_VEGA/config.local.sh" ] && . "$HERE_VEGA/config.local.sh"

# --- SLURM -------------------------------------------------------------------
# Limits checked on Vega on 2026-10-26: walltime at most 2 days, default 10 min
# (so --time is always set), MaxArraySize 30,000, no job-count limits on the
# account. The budget, 5,000 CPU node-hours from 16. 10. 2026, is not
# enforced by SLURM but tracked by SLING. Billing: CPU = 1.0, memory 1 GB =
# 1.0, so memory above 1 GB per core costs like extra cores.
# Project account (allocation S26T11-01).
: "${ACCOUNT:=s26t11-01-users}"
: "${PARTITION:=cpu}"
# Cores per job: the random forest fits its 100 trees on these, and
# NSGAII-MIIP computes its mutual-information matrix on them.
: "${CPUS:=8}"
# Memory per job: 1 GB per core, Vega's default and free of extra billing.
: "${MEM:=8G}"
# Memory for the cells in the experiment's HIGHMEM_CELLS file (HSIC Lasso on
# the wide sets, ReliefF on EOData, NSGAII-MIIP on Heartbeat).
: "${HIGHMEM:=64G}"
# At most this many tasks of one array at once (sbatch --array=...%N).
: "${MAX_PARALLEL:=200}"
# SLURM's array index limit (MaxArraySize - 1).
: "${MAX_ARRAY_INDEX:=29999}"

# --- software ------------------------------------------------------------------
# The Python environment lives on Ceph as ONE archive, built by setup.sh, and
# is unpacked onto local disk wherever it runs (env.sh). Never as loose files
# on Ceph: on 2026-10-26 a Miniforge install of tens of thousands of small
# files into the home directory took an hour, hung, and could not be deleted.
: "${ENV_ARCHIVE:=$REPO/.hpc/env.tar.gz}"
# Node-local scratch: on compute nodes /tmp is a 1.8 TB NVMe disk.
: "${LOCAL_TMP:=/tmp}"
: "${PYTHON_VERSION:=3.11}"
: "${MICROMAMBA_URL:=https://micro.mamba.pm/api/micromamba/linux-64/latest}"
# The FASTENER clone the experiments ran with (DEC-40, DEC-41).
: "${FASTENER_URL:=https://github.com/klemenkenda/FASTENER}"
# From H8-E01: 9226b90, with the guidance hooks (DEC-49); H10 and earlier ran
# on 3be5697 (their manifests record it).
: "${FASTENER_COMMIT:=9226b90}"

# Inside a job, a PATH with nothing on a network mount: on 2026-10-26 a PATH
# entry on a hung mount froze `which`, and with it every command that
# searched PATH. On a login node PATH is left alone, since SLURM's own
# commands may live elsewhere.
[ -n "${SLURM_JOB_ID:-}" ] && export PATH="/usr/bin:/bin"

. "$HERE_VEGA/env.sh"
